import { redirect } from 'next/navigation'
import { SetPasswordForm } from '@/domains/identity'
import { resolveTenant } from '@/lib/tenant'
import { currentUser } from '@/lib/session'

/**
 * Choose a password, for an account the clinic created.
 *
 * WHO ARRIVES HERE. A patient registered at the front desk, whose temporary password was
 * generated by a member of staff and read out to them. The credential guarding this
 * person's consultations and prescriptions is therefore currently known to somebody else,
 * which is the whole reason the screen exists — and why the account carries the
 * change-required flag until it is used, and why /account sends a flagged patient back
 * here rather than letting them browse past it.
 *
 * A GUEST IS REDIRECTED TO SIGN-IN, not shown the form. This screen is reached while
 * already signed in with the temporary password: it asks for that password as proof, so a
 * caller with no session has nothing to prove and nothing to change.
 *
 * No SiteShell, for the same reason as sign-in: it is a full-bleed split screen, and a
 * header above it would leave the clinic's panel floating in the middle of the page.
 *
 * @see docs/40-api/authentication-and-sessions.md
 */
export default async function SetPasswordPage({
  searchParams,
}: {
  searchParams: Promise<{ error?: string }>
}) {
  const [tenant, user, params] = await Promise.all([resolveTenant(), currentUser(), searchParams])

  if (!user) {
    redirect('/sign-in')
  }

  return <SetPasswordForm tenant={tenant} error={params.error} />
}
